G=load(); print(sorted(G))
# collect exact structures
for k in [1,2,3,4,5,6]:
    I_,O_=G[f'Demo pair {k} input'],G[f'Demo pair {k} output']
    H,W=len(I_),len(I_[0])
    dots=[(r,c,I_[r][c]) for r in range(H) for c in range(W) if I[r][c]!=0]
    # strokes: maximal runs of consecutive 5s in a row or column
    runs=[]
    for rr in range(H):
        cc=0
        while cc<W:
            if O_[rr][cc]==5:
                c2=cc
                while c2<W and O_[rr][c2]==5: c2+=1
                runs.append(('h',rr,cc,c2-1))
                cc=c2
            else:
                cc+=1
    for cc in range(W):
        rr=0
        while rr<H:
            if O_[rr][cc]==5:
                r2=rr
                while r2<H and O_[r2][cc]==5: r2+=1
                runs.append(('v',rr,cc,r2-1))
                rr=r2
            else:
                rr+=1
    dset=set((r,c) for r,c,col in dots)
