        rs=[r for r,c,v in runs if (r,c) in dset or dot in [(r,c) for r,c,_ in [[None]]] ]
        comp=[run for run in runs if any(abs(run[1]-dot[0])<=1 and abs(run[2]-dot[1])<=1 for run in [runs])]
