G=load()

def analyze(k):
    I_,O_=G[f'Demo pair {k} input'],G[f'Demo pair {k} output']
    H,W=len(I_),len(I_[0])
    dots=[(r,c,I_[r][c]) for r in range(H) for c in range(W) if I_[r][c]!=0]
    # stroke cells per dot: nonzero output cells adjacent (within radius 5) to dot, excluding original dot color elsewhere far away
    for dot in dots:
        r,c,col=dot
        added=[(rr,cc,O_[rr][cc]) for rr in range(H) for cc in range(W)
               if O_[rr][cc]!=I_[rr][cc] and max(abs(rr-r),abs(cc-c))<=6]
        # classify each added cell as on-stroke vs stray
        comps=[]; seen=set()
        for cell in added:
            if cell in seen: continue
            stack=[cell]; comp=[]
            while stack:
                x,y=stack.pop()
                if (x,y) in seen: continue
                seen.add((x,y)); comp.append((x,y))
                for dx in(-1,0,1):
                    for dy in(-1,0,1): stack.append((x+dx,y+dy))
            comps.append(comp)
        print(' pair',k,'dot',(r,c,col),'comps:')
        for comp in comps:
            cols={v for _,_,v in comp}
            rel=[(x-r,y-c,v) for x,y,v in comp]
            print('   n=',len(comp),'colors',cols,rel)
